import * as T from 'three';
import {batchMeshes} from './optimize.js';
import {RoundedBoxGeometry} from 'three/addons/geometries/RoundedBoxGeometry.js';
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js';
export const ASSETS={vehicle:null,robot:null,ball:null};
export const palette=[0x43edb1,0xffbb32,0x34cfff,0xff386a];
const shell=new T.MeshStandardMaterial({color:0x283a56,metalness:.7,roughness:.3}),dark=new T.MeshStandardMaterial({color:0x080e1d,metalness:.5,roughness:.35}),silver=new T.MeshStandardMaterial({color:0x7995b0,metalness:.75,roughness:.28});
const geometry=new RoundedBoxGeometry(1,1,1,2,.12),sphere=new T.SphereGeometry(1,16,12);
export const glow=(color,intensity=3)=>new T.MeshStandardMaterial({color,emissive:color,emissiveIntensity:intensity,roughness:.3,metalness:.25});
function mesh(g,m,parent,p,s){const a=new T.Mesh(g,m);a.position.set(...p);a.scale.set(...s);a.castShadow=a.receiveShadow=true;parent.add(a);return a;}
const box=(p,m,v,s)=>mesh(geometry,m,p,v,s);
async function replacement(root,path,placeholder,color){if(!path)return;try{const {scene}=await new GLTFLoader().loadAsync(path);scene.traverse(o=>{if(!o.isMesh)return;o.castShadow=o.receiveShadow=true;const list=(Array.isArray(o.material)?o.material:[o.material]).map(m=>{m=m.clone();if(color!==undefined&&/^team/i.test(m.name)){m.color.setHex(color);if(/emission/i.test(m.name))m.emissive.setHex(color);}return m;});o.material=list.length===1?list[0]:list;});root.remove(placeholder);root.add(scene);}catch(e){console.warn('Using placeholder because asset did not load',e);}}
export function vehicle(color){const root=new T.Group(),body=new T.Group(),robotMount=new T.Group(),robot=new T.Group();root.add(body,robotMount);robotMount.position.set(0,.8,-.18);robotMount.add(robot);const team=new T.MeshStandardMaterial({color,metalness:.5,roughness:.3}),lit=glow(color),amber=glow(0xffa62b,2);
box(body,dark,[0,.23,0],[3.15,.4,1.8]);box(body,shell,[0,.5,0],[2.75,.45,1.6]);box(body,silver,[0,.68,.48],[2.65,.18,.45]);box(body,dark,[0,.63,.91],[2.7,.36,.16]);box(body,lit,[0,.65,1.01],[1.9,.14,.06]);box(body,team,[0,.4,.98],[2.6,.12,.09]);
for(const s of [-1,1]){box(body,shell,[s*1.4,.52,0],[.45,.7,1.75]);box(body,team,[s*1.4,.88,-.08],[.43,.1,1.25]);box(body,amber,[s*1.45,.6,.91],[.22,.24,.08]);box(body,lit,[s*1.58,.34,.1],[.05,.13,1.1]);for(let j=0;j<4;j++)box(body,silver,[s*1.4,.89,-.55+j*.23],[.24,.035,.06]);}
box(body,dark,[0,.74,-.38],[1.25,.5,.55]);box(body,shell,[0,.95,.3],[1.3,.15,.3]);box(body,lit,[0,1.04,.3],[.65,.025,.15]);box(robot,team,[0,.36,0],[.7,.65,.5]);box(robot,silver,[0,.63,.01],[.55,.14,.4]);mesh(sphere,silver,robot,[0,1,0],[.48,.48,.43]);box(robot,team,[0,1.32,-.03],[.16,.2,.45]);box(robot,dark,[0,1.04,.34],[.78,.29,.18]);box(robot,lit,[0,1.04,.445],[.63,.085,.025]);for(const s of [-1,1]){mesh(sphere,team,robot,[s*.5,.52,.05],[.24,.24,.24]);const arm=box(robot,shell,[s*.56,.31,.26],[.23,.45,.23]);arm.rotation.x=-.6;mesh(sphere,silver,robot,[s*.55,.16,.45],[.16,.16,.16]);}
const pulse=new T.Mesh(new T.TorusGeometry(1.7,.045,6,48,Math.PI),new T.MeshBasicMaterial({color,transparent:true,opacity:0}));pulse.rotation.x=Math.PI/2;pulse.position.set(0,.15,.2);root.add(pulse);batchMeshes(body);batchMeshes(robot);root.userData={body,robot,pulse};replacement(root,ASSETS.vehicle,body,color);replacement(robotMount,ASSETS.robot,robot,color);return root;}
// Shared static reflection environment: crisp studio strips, no per-frame capture.
let ballEnvironment;
function reflectionMap(){if(ballEnvironment)return ballEnvironment;const faces=Array.from({length:6},(_,i)=>{const c=document.createElement('canvas');c.width=c.height=128;const g=c.getContext('2d');g.fillStyle=i===3?'#101622':'#596776';g.fillRect(0,0,128,128);g.fillStyle='#eaf4ff';g.fillRect(18,0,18,128);g.fillStyle='#a3b6c7';g.fillRect(78,0,34,128);g.fillStyle='#1a2638';g.fillRect(0,88,128,40);return c;});ballEnvironment=new T.CubeTexture(faces);ballEnvironment.colorSpace=T.SRGBColorSpace;ballEnvironment.needsUpdate=true;return ballEnvironment;}
const ballGeometry=new T.SphereGeometry(.255,32,20);
export function ball(){const root=new T.Group(),visual=new T.Group();root.add(visual);const material=new T.MeshStandardMaterial({color:0xc4d0dc,metalness:1,roughness:.12,envMap:reflectionMap(),envMapIntensity:1.3,emissive:0x000000});visual.add(new T.Mesh(ballGeometry,material));root.userData.material=material;replacement(root,ASSETS.ball,visual);return root;}
export function colorBall(root,owner){const color=palette[owner]??0xc4d0dc;if(root.userData.teamColor===color)return;root.userData.teamColor=color;root.traverse(o=>{if(!o.isMesh)return;for(const m of Array.isArray(o.material)?o.material:[o.material]){if(m.color)m.color.setHex(color);}});}
